insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e2d29a05-74ae-4b31-aca7-80900ef79215', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$inleiding: marathonschaatser Arthur met mogelijk ijzertekort$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context1.png$$,
   $$Arthur is een getalenteerde marathonschaatser en traint iedere dag. Zijn prestaties zijn de laatste tijd echter iets teruggelopen. Zijn trainer denkt dat dit veroorzaakt wordt door ijzertekort.$$, 'inline'),
  ('05e9e043-16a0-4f2d-8c9b-1aa671cc6e32', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$ijzertekort en een verlaagd hemoglobinegehalte$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context2.png$$,
   $$IJzertekort kan leiden tot een verlaagd hemoglobinegehalte in het bloed.$$, 'inline'),
  ('1b55a9aa-6366-4283-a6b5-64ffffbdcbd7', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$kader: ijzer, ferritine en de formule voor aan ferritine gebonden ijzer$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context3.png$$,
   $$IJzer is een essentiële, maar ook giftige voedingsstof. Vrije ijzer-ionen (Fe²⁺ of Fe³⁺) veroorzaken namelijk schade aan weefsels. Vrijwel al het ijzer in het lichaam is gebonden aan eiwitten en de ijzeropname vanuit de darmen wordt nauwkeurig gereguleerd. Ferritine is een eiwit dat ijzer kan opslaan door het te binden. Vrijwel alle ferritine bevindt zich in cellen, maar er is ook een kleine hoeveelheid aanwezig in bloedplasma. Met behulp van de volgende formule kan de totale hoeveelheid ijzer die in het lichaam aan ferritine gebonden is (Y) worden bepaald:
Y = 120 × m × FB Y: aan ferritine gebonden ijzer in het lichaam (in µg) m: lichaamsgewicht (in kg) FB: ferritinegehalte bloedplasma (in µg/L)$$, 'inline'),
  ('175cbff8-36aa-4a9d-ade5-6c39c90509f8', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$bloedonderzoek bij de sportarts: hematocrietwaarde$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context4.png$$,
   $$De trainer stuurt Arthur naar de sportarts. Zij onderzoekt hoeveel procent van het bloedvolume wordt ingenomen door rode bloedcellen: de hematocrietwaarde. Verder onderzoekt zij het hemoglobinegehalte en het ferritinegehalte in het bloed van Arthur. De resultaten van het bloedonderzoek van Arthur worden vergeleken met de gemiddelde waarden van mannen (tabel 1).$$, 'inline'),
  ('7f9ecad5-2fa4-43e6-b401-c2e04f559a87', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$tabel 1: bloedwaarden van Arthur en gemiddelde waarden van mannen$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context5.png$$,
   $$tabel 1 (Arthur / gemiddelde waarde mannen):
hematocrietwaarde bloed (in %): 41 / 47
hemoglobinegehalte bloed (in mmol/L): 9,2 / 9,8
ferritinegehalte bloedplasma (in µg/L): 17 / 150
lichaamsgewicht (in kg): 68 / 85$$, 'inline'),
  ('48c477e5-1738-49d5-824f-b90aef4a9e46', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$drie uitspraken naar aanleiding van het bloedonderzoek$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context6.png$$,
   $$Naar aanleiding van het bloedonderzoek worden de volgende uitspraken gedaan:
1 Het volumepercentage rode bloedcellen in het bloed van Arthur is lager dan gemiddeld.
2 De hoeveelheid hemoglobine per rode bloedcel is bij Arthur lager dan gemiddeld.
3 De totale hoeveelheid aan ferritine gebonden ijzer is bij Arthur ongeveer 1,4 gram lager dan gemiddeld.$$, 'inline'),
  ('a1378853-de5f-4133-b74f-d587234222fe', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$ijzeropname door een darmcel (afbeelding 1)$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context7.png$$,
   $$Het bloedonderzoek doet vermoeden dat Arthur een dreigend ijzertekort heeft. Hij gaat op advies van de arts meer ijzerhoudende voedingsmiddelen eten, in combinatie met groenten en fruit met een hoog vitamine-C-gehalte.
In de darmen wordt ijzer opgenomen in de vorm van Fe²⁺. Afbeelding 1 laat zien dat een darmcel een Fe²⁺-ion opneemt met behulp van het membraaneiwit Dmt1.
In de darmcel is het eiwit ferritine aanwezig. Het transporteiwit ferroportine transporteert Fe²⁺-ionen vanuit de darmcel naar het bloed.
afbeelding 1: darmcel tussen de darmholte (boven) en het bloed (onder). Fe²⁺ gaat vanuit de darmholte via het membraaneiwit Dmt1 de cel in; in de cel kan Fe²⁺ worden gebonden aan of vrijkomen uit ferritine; via ferroportine gaat Fe²⁺ de cel uit naar het bloed.$$, 'inline'),
  ('c2bc6223-93c7-4f7b-b39e-eabef244c78c', 'e962fccf-727f-4591-b554-01ce6e8b6668', $$aanpassing van genexpressie bij een lage ijzerconcentratie$$,
   $$biologie-havo-2022-ii-ijzertekort-in-de-topsport-context8.png$$,
   $$Bij een lage ijzerconcentratie in het bloed wordt de expressie van bepaalde genen aangepast zodat meer ijzer uit de voeding kan worden opgenomen. Hierdoor stijgt de ijzerconcentratie in het bloed.$$, 'inline'),
  ('28c2eb1d-78fa-48cf-93e9-78b017f643ef', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$inleiding: avocado als gezonde keuze$$,
   $$biologie-havo-2022-ii-avocado-context1.png$$,
   $$Naomi is gek op avocado’s. Deze vruchten staan bekend als een gezonde keuze in het dieet van de mens.$$, 'inline'),
  ('75ee27d2-9bee-4667-8225-fc3c28553759', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$kader: onverzadigde vetten en kalium en de bloeddruk$$,
   $$biologie-havo-2022-ii-avocado-context2.png$$,
   $$Avocado’s zijn rijk aan onverzadigde vetten, vitamine B en kalium. De onverzadigde vetten en kalium hebben een gunstig effect op de bloeddruk. Onverzadigde vetten beïnvloeden de wanden van de bloedvaten en kalium-ionen bevorderen de uitscheiding van natrium-ionen door de nieren.$$, 'inline'),
  ('6f6a2347-2c73-4f88-811f-b5afa1a52988', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$natrium-inname, bloeddruk en vaatverwijding$$,
   $$biologie-havo-2022-ii-avocado-context3.png$$,
   $$Na het eten van voedingsmiddelen met veel natrium-ionen stijgt de bloeddruk. Doordat vervolgens vaatverwijding optreedt, zal de bloeddruk weer dalen.$$, 'inline'),
  ('c5282414-de04-4730-8096-d4aebf9f6d10', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$uitscheiding van natrium-ionen door de nieren$$,
   $$biologie-havo-2022-ii-avocado-context4.png$$,
   $$Bij de regulatie van de bloeddruk op langere termijn is de uitscheiding van natrium-ionen in de nieren van belang.$$, 'inline'),
  ('aa7a8038-ad45-4bdf-8b47-cd0a4b84bba7', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$onverzadigde vetten en de bloedvatwanden$$,
   $$biologie-havo-2022-ii-avocado-context5.png$$,
   $$Onverzadigde vetten dragen bij aan een gezonde bloeddruk doordat ze de wanden van de bloedvaten gunstig beïnvloeden.$$, 'inline'),
  ('cf1eed71-5f95-40f1-bd4d-b83fef23ff1d', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$kader: groeiomstandigheden van de avocadoplant en wortelrot door fytoftora$$,
   $$biologie-havo-2022-ii-avocado-context6.png$$,
   $$Naomi wil nu zelf een avocadoplant gaan kweken. Op een website leest zij:
“Voor een goede groei van de avocadoplant mag de temperatuur niet onder de 10 °C komen en moet de bodem niet te droog zijn. Avocadoplanten wortelen voornamelijk in de bovenste laag van de bodem en bezitten weinig wortelhaartjes. Maar als de grond rondom de wortels continu nat is, gaan de wortels rotten. Een belangrijke veroorzaker van wortelrot is fytoftora (Phytophthora cinnamomi).”$$, 'inline'),
  ('e466bfcb-357c-4a1f-8688-79067389bcfc', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$Naomi kweekt een avocadoplant; drie milieufactoren$$,
   $$biologie-havo-2022-ii-avocado-context7.png$$,
   $$Naomi gebruikt de pit van een avocado die zij in de supermarkt heeft gekocht om een avocadoplant te kweken. Nadat de pit is gekiemd, doet ze hem in een pot met luchtige grond. Naomi plaatst de pot in een helder verlichte ruimte met een constante temperatuur van 11 °C. Ze geeft de gekiemde pit weinig water. Milieufactoren zijn:
1 temperatuur
2 water
3 zuurstof$$, 'inline'),
  ('23d47106-e921-4423-acaa-149d2085f592', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$kader: zoösporen van fytoftora$$,
   $$biologie-havo-2022-ii-avocado-context8.png$$,
   $$De beweeglijke sporen (zoösporen) van fytoftora verplaatsen zich door het water in de grond en dringen plantenwortels binnen. In de wortel ontwikkelt de zoöspore zich tot een meercellige zwamvlok die sporendoosjes produceert waarin nieuwe sporen worden gevormd.$$, 'inline'),
  ('09c86cce-7862-4a7e-821f-20831895246f', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$drie uitspraken over fytoftora$$,
   $$biologie-havo-2022-ii-avocado-context9.png$$,
   $$Over fytoftora worden de volgende uitspraken gedaan:
1 Fytoftora behoort tot de bacteriën.
2 Fytoftora behoort tot de producenten.
3 Fytoftora is een heterotroof organisme.$$, 'inline'),
  ('e3e3029c-ab8b-4085-9939-f13b542eb8ad', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$met water verzadigde bodem verzwakt de wortels$$,
   $$biologie-havo-2022-ii-avocado-context10.png$$,
   $$Als het lang en hard regent op een avocadoplantage kan de grond verzadigd raken met water waardoor de wortels van de avocadoplanten verzwakt raken. Dit maakt het voor de zoösporen gemakkelijker om de plantenwortels binnen te dringen. Een belangrijke oorzaak van de verzwakking van de wortels is een afname van de stofwisseling in de wortelcellen.$$, 'inline'),
  ('4c31ad16-e169-4e92-9949-55e47683548a', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$kader: enten van avocadoplanten$$,
   $$biologie-havo-2022-ii-avocado-context11.png$$,
   $$Naomi weet dat avocadoplanten op plantages vaak zijn geënt. De rassen die de hoogste opbrengst geven, hebben namelijk een wortelstelsel dat gevoeliger is voor fytoftora-infecties dan rassen die minder en kleinere vruchten dragen. Bij het enten wordt een stengel van een ras met een hoge opbrengst geplaatst op een wortelstelsel van een ras dat resistent is tegen fytoftora- infecties in het wortelstelsel. Na het enten vergroeien de vaatstelsels van wortelstelsel en stengel op zo’n manier dat transport van stengel naar bladeren en van bladeren naar stengel kan plaatsvinden en de avocadoplant kan groeien.$$, 'inline'),
  ('c027b92c-9627-46c6-b4eb-bc108f66a7eb', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$afbeelding 1: doorsnedes van wortel en stengel met vaten P, Q, R en S$$,
   $$biologie-havo-2022-ii-avocado-context12.png$$,
   $$afbeelding 1: tekening van een jonge avocadoplant met een doorsnede van de wortel (links) en een doorsnede van de stengel (rechts). In de wortel wijzen P en Q naar vaten in het centrale vaatweefsel; in de stengel wijzen R en S naar vaten in een vaatbundel.$$, 'inline'),
  ('5926718a-254f-495f-997d-58782b025cd1', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$in twee van de vaten vindt de anorganische sapstroom plaats$$,
   $$biologie-havo-2022-ii-avocado-context13.png$$,
   $$In afbeelding 1 zijn doorsnedes van een wortel en de stengel van een jonge plant weergegeven. Met de letters P, Q, R en S zijn vaten aangegeven. In twee van deze vaten vindt de anorganische sapstroom plaats.$$, 'inline'),
  ('c36f9660-ef96-41c3-a33f-ca11af34797e', '97818a1c-1fbd-4acf-923b-3d18a931c469', $$bestuiving en vruchtvorming bij geënte avocadobomen$$,
   $$biologie-havo-2022-ii-avocado-context14.png$$,
   $$Op een avocadoplantage bestuiven de bloemen van de geënte avocadobomen elkaar. Uit een bloem ontwikkelt zich na bevruchting een avocado (vrucht) met een pit (zaad).$$, 'inline'),
  ('55f86274-c84d-461b-86fd-5c89ce92da92', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$inleiding: voorlichtingsavond over borstvoeding$$,
   $$biologie-havo-2022-ii-borstvoeding-context1.png$$,
   $$Ava en haar partner Glenn verwachten binnenkort hun eerste kind. Ze bezoeken een voorlichtingsavond over borstvoeding. Lactatiekundige Rosanne geeft informatie.$$, 'inline'),
  ('d9d3b87a-fba5-4b0c-a42e-d5efbc12c146', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$kader: veranderingen in het borstweefsel en melkkliertjes (afbeelding 1)$$,
   $$biologie-havo-2022-ii-borstvoeding-context2.png$$,
   $$Tijdens de zwangerschap vinden veranderingen plaats in het borstweefsel van een vrouw. Het aantal melkkanaaltjes neemt toe en dekweefselcellen van de melkkanaaltjes differentiëren zich tot melkproducerende kliercellen. Groepjes van deze cellen vormen samen de melkkliertjes. Rondom elk melkkliertje ontwikkelen zich speciale oxytocine-gevoelige spiercellen. Als deze spiercellen zich samentrekken, wordt melk in de melkkanaaltjes geperst (afbeelding 1).
afbeelding 1: doorsnede van een borst met een vergroting van melkkliertjes; aangegeven zijn een melkkanaaltje, een kliercel en een spiercel.$$, 'inline'),
  ('ab07338b-c29e-4536-ad32-c4142324af11', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$melkproductie en de afgifte van oxytocine$$,
   $$biologie-havo-2022-ii-borstvoeding-context3.png$$,
   $$Na de bevalling komt de melkproductie meestal goed op gang. Als zintuigcellen in de tepel gestimuleerd worden, ontstaan impulsen in sensorische zenuwcellen. De impulsen worden verwerkt in het centraal zenuwstelsel. Dit leidt tot de afgifte van oxytocine. Oxytocine komt vervolgens terecht bij de melkkliertjes.$$, 'inline'),
  ('84f00519-c81b-44f7-8130-71eb3ae74455', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$het FIL-eiwit en een uitspraak met twee ontbrekende woorden$$,
   $$biologie-havo-2022-ii-borstvoeding-context4.png$$,
   $$Rosanne adviseert om een borst steeds helemaal leeg te laten drinken door de baby. De melkproductie wordt namelijk gestimuleerd doordat de borst leeg is. Het FIL-eiwit dat aanwezig is in moedermelk regelt dit proces. Over het FIL-eiwit wordt een uitspraak gedaan waarin twee woorden ontbreken: De aanwezigheid van FIL-eiwit …(1)… de aanmaak van moedermelk; dit proces heet …(2)… terugkoppeling.$$, 'inline'),
  ('24353499-d7c7-4a18-b911-18818cfc2dd2', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$antistoffen in moedermelk$$,
   $$biologie-havo-2022-ii-borstvoeding-context5.png$$,
   $$Glenn vraagt wat het verschil in samenstelling is tussen flesvoeding en borstvoeding. Rosanne antwoordt dat moedermelk antistoffen bevat. Daardoor is de baby gedurende de periode van borstvoeding immuun voor veel ziekten, zoals maag- en darminfecties.$$, 'inline'),
  ('17908947-22ee-42f6-96d8-e5b3bbc0f6f2', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$kader: oligosachariden zoals lacto-N-tetraose (afbeelding 2)$$,
   $$biologie-havo-2022-ii-borstvoeding-context6.png$$,
   $$Rosanne noemt nog een ander voordeel van borstvoeding: moedermelk stimuleert een gunstige soortensamenstelling van darmbacteriën bij de baby.
Moedermelk bevat namelijk oligosachariden die voor de baby onverteerbaar zijn, zoals lacto-N-tetraose (afbeelding 2). Deze oligosachariden kunnen wel worden afgebroken door bepaalde gunstige darmbacteriën, de bifidobacteriën.
afbeelding 2: structuurformule van lacto-N-tetraose: een keten van vier ringvormige suikereenheden met OH-groepen (één eenheid met een NHAc-groep).$$, 'inline'),
  ('2d3a614a-fe29-4015-9cef-1c219b6db328', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$drie uitspraken over lacto-N-tetraose$$,
   $$biologie-havo-2022-ii-borstvoeding-context7.png$$,
   $$Over lacto-N-tetraose in borstvoeding worden de volgende uitspraken gedaan:
1 Bij baby’s die borstvoeding krijgen, hebben bifidobacteriën een selectievoordeel ten opzichte van bacteriën die geen oligosachariden kunnen afbreken.
2 De klieren in het spijsverteringsstelsel van baby’s produceren geen enzymen voor de afbraak van lacto-N-tetraose.
3 Lacto-N-tetraose bestaat uit een keten van aminozuren.$$, 'inline'),
  ('a2675600-7d19-4fbd-9acd-2ea5b7e2bf98', '61bf2955-17b7-4757-a627-3a72bdb2eb79', $$minder bifidobacteriën, darmperistaltiek en diarree$$,
   $$biologie-havo-2022-ii-borstvoeding-context8.png$$,
   $$Bij een baby met minder bifidobacteriën in de darm kunnen schadelijke bacteriën in de darm zich makkelijker vermeerderen. Hierdoor kunnen ontstekingen in de dikke darm ontstaan die leiden tot een sterke toename van de darmperistaltiek. Door verminderde waterresorptie kan dan diarree ontstaan.$$, 'inline'),
  ('d7ea4542-2866-49d8-b083-ad1a2e43851c', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$inleiding: bedreigde Indische bruinvissen in de Yangtze (afbeelding 1)$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context1.png$$,
   $$In de rivier de Yangtze (Chang Jiang) in China leeft een populatie Indische bruinvissen (afbeelding 1). Deze populatie wordt ernstig met uitsterven bedreigd. In 2018 waren er nog maar ongeveer 1000 Indische bruinvissen in de Yangtze.
afbeelding 1: foto van een bruinvis$$, 'inline'),
  ('d710c61c-deee-484e-9933-6e8020992bd5', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$kader: verspreiding van de Yangtze-variant en de zoutwatervariant (afbeelding 2)$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context2.png$$,
   $$De bruinvissen in de Yangtze leven in kleine groepen. Deze zoogdieren jagen op vissen, weekdieren en kreeftachtigen. In de zeeën rond China komt ook een variant voor van de Indische bruinvis. In afbeelding 2 is de verspreiding van de Yangtze-variant en de zoutwatervariant weergeven.
afbeelding 2: kaart van China; de Yangtze-variant leeft in de rivier de Yangtze, de zoutwatervariant in de kustzeeën (Gele Zee en Zuid-Chinese Zee).$$, 'inline'),
  ('7d90e622-cf9d-4383-9c72-c78d6ca83aab', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$geografische isolatie van de twee varianten$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context3.png$$,
   $$Om te bepalen of de twee varianten aparte soorten zijn, hebben onderzoekers het genoom van deze Indische bruinvissen bestudeerd. Omdat de Yangtze-bruinvissen geografisch geïsoleerd zijn van de zoutwaterbruinvissen, treedt er geen voortplanting op tussen deze twee varianten.$$, 'inline'),
  ('7926695d-63a6-4ea6-8f86-9ad9f7ce148f', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$DNA-verschillen: allelen voor overleven bij lage zuurstofconcentratie$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context4.png$$,
   $$De onderzoekers vonden verschillen in het DNA van de zoutwatervariant en dat van de Yangtze-variant. Binnen populaties van de zoutwatervariant is er een hogere frequentie van allelen die helpen overleven bij een lage zuurstofconcentratie in het lichaam. In zee zijn deze allelen gunstig omdat bruinvissen aan het wateroppervlak lucht inademen en daarna in zee op grote diepte hun prooien vangen.$$, 'inline'),
  ('f2fede73-36ee-47ef-82bb-ed0ec23f5651', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$genetische verschillen in ADH-afgifte en urineproductie$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context5.png$$,
   $$De twee varianten Indische bruinvissen verschillen ook in genen die te maken hebben met de aanpassing aan de osmotische waarde van het water waarin ze leven. Deze genetische verschillen leiden tot een verschil in afgifte van ADH en in de osmotische waarde van de urine. Yangtze- bruinvissen produceren daardoor meer urine dan zoutwaterbruinvissen.$$, 'inline'),
  ('a96a0065-5c68-4a63-877f-78e340d4ca08', 'aa8cc64c-7049-4e6a-af8e-1161e998c4d1', $$twee aparte soorten en het risico van uitsterven$$,
   $$biologie-havo-2022-ii-hoelang-nog-voor-de-yangtze-bruinvissen-context6.png$$,
   $$Door de grote genetische verschillen die ze vonden, zijn de onderzoekers nu van mening dat er sprake is van twee aparte soorten. Dit is een extra reden om de Indische bruinvissen in de Yangtze te beschermen om ze te behoeden voor uitsterven. De kans is groot dat de populatie Yangtze-bruinvissen zal uitsterven als de populatiegrootte tot minder dan honderd dieren is gedaald.$$, 'inline'),
  ('3dabcd06-5c27-4c5d-93f0-7c8bb0e953d7', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$inleiding: onderzoek naar bacteriën bij zoenen$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context1.png$$,
   $$Zoenen is heerlijk als je verliefd bent. Maar als je er goed over nadenkt, heeft het ook iets onsmakelijks: je wisselt tijdens het zoenen speeksel, etensresten, virussen en bacteriën uit. Microbioloog Remco Kort deed er onderzoek naar.$$, 'inline'),
  ('aab37d08-0f41-4635-97df-7f80215301c7', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$kader: het speekselmicrobioom van verliefde stelletjes$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context2.png$$,
   $$In en op ons lichaam leven veel micro-organismen: bacteriën, gisten en andere eencelligen. Samen vormen ze ons microbioom. Remco Kort onderzocht bij verliefde stelletjes de overeenkomst in samenstelling van het speekselmicrobioom voor en na een tongzoen, en het aantal bacteriën dat bij een tongzoen wordt overgedragen. Hij nam bij de geliefden wat speeksel af op verschillende tijdstippen en onderzocht de monsters. Zowel voor als na een tongzoen van tien seconden bleek een stelletje een meer overeenkomstig speekselmicrobioom te hebben dan een willekeurig tweetal.$$, 'inline'),
  ('773fc510-0173-4752-9ecb-ede0878cfa82', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$overeenkomst vóór de tongzoen, bijvoorbeeld door dezelfde tandpasta$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context3.png$$,
   $$De overeenkomst vóór de tongzoen kan veroorzaakt zijn door zoengedrag in de periode voorafgaand aan het onderzoek, maar er zijn ook andere verklaringen mogelijk, zoals het gebruik van dezelfde soort tandpasta.$$, 'inline'),
  ('96a3adc0-fd07-48ee-9b40-7ab39e16cae4', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$hypothese over zoenfrequentie en het verschil in microbioom$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context4.png$$,
   $$Korts hypothese was dat er meer overeenkomst is in het speekselmicrobioom bij stelletjes met een hoge zoenfrequentie dan bij stelletjes met een lage zoenfrequentie. De stelletjes beantwoordden vragen over hun zoengedrag en Kort verwerkte de resultaten in een diagram, waarin het verschil in microbioom is uitgedrukt op een schaal van 0,0 (volledig gelijk) tot 1,0 (volledig verschillend).$$, 'inline'),
  ('3457edf5-ec9f-4f42-a74f-7efcec16cd77', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$de resultaten ondersteunden de hypothese$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context5.png$$,
   $$De resultaten van zijn onderzoek ondersteunden zijn hypothese. In afbeelding 1 zijn vier diagrammen weergegeven.$$, 'inline'),
  ('a9117e96-10b2-4854-9b3b-618bf30fd4f0', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$afbeelding 1: vier diagrammen$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context6.png$$,
   $$afbeelding 1: vier diagrammen. Diagram 1: aantal zoenen per week (0-120, verticaal) tegen verschil in speekselmicrobioom (0-1,0, horizontaal), stijgende lijn. Diagram 2: dezelfde assen, dalende lijn. Diagram 3: verschil in speekselmicrobioom (0-1,0, verticaal) tegen aantal zoenen per week (0-120, horizontaal), stijgende lijn. Diagram 4: dezelfde assen als diagram 3, dalende lijn.$$, 'inline'),
  ('85e8c788-891f-4fb8-8e77-be44f769193e', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$kader: vervolgonderzoek met een yoghurtdrankje (afbeelding 2 en 3)$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context7.png$$,
   $$In een vervolgonderzoek met drie stelletjes wilde Kort te weten komen hoeveel bacteriën overgedragen worden bij een tongzoen. Hij gebruikte een yoghurtdrankje met bepaalde melkzuurbacteriën die nauwelijks in de mond voorkomen. Het onderzoek verliep zoals weergegeven in afbeelding 2.
afbeelding 2: tijdlijn voor donor en ontvanger: meting 1 (ontvanger), yoghurtdrankje (donor), meting 2 (donor), tongzoen van tien seconden, meting 3 (ontvanger).
− Het percentage melkzuurbacteriën in het speekselmicrobioom van de ontvanger wordt bepaald (meting 1).
− Eén persoon (de donor) van het stelletje drinkt het yoghurtdrankje.
− Hierna wordt het percentage melkzuurbacteriën in het speekselmicrobioom van de donor bepaald (meting 2).
− Er volgt een tongzoen van tien seconden.
− Direct daarna wordt nogmaals het percentage melkzuurbacteriën in het speekselmicrobioom van de ontvanger bepaald (meting 3).
De resultaten staan in afbeelding 3.
afbeelding 3: staafdiagram van het percentage melkzuurbacteriën: meting 1 ongeveer 0,5; meting 2 ongeveer 7,8; meting 3 ongeveer 1,1.$$, 'inline'),
  ('a0f8f5c9-d51b-47ca-89eb-0827408301e9', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$twee uitspraken over het onderzoek met ontbrekende woorden$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context8.png$$,
   $$Over het onderzoek worden twee uitspraken gedaan. In elke uitspraak is een woord weggelaten.
− Doordat gebruik werd gemaakt van melkzuurbacteriën die nauwelijks in de mond voorkomen werd de …(1)… van dit onderzoek beïnvloed.
− Doordat meerdere stelletjes werden onderzocht, werd de …(2)… van dit onderzoek beïnvloed.$$, 'inline'),
  ('f5408252-220e-4f67-aafc-3f6146eeaf1b', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$ziekmakende bacteriën, een stabiel microbioom en antibiotica$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context9.png$$,
   $$Bij een tongzoen worden mogelijk ook ziekmakende bacteriën overgedragen. Meestal krijgen deze bacteriën, die bijvoorbeeld ontstoken tandvlees of cariës veroorzaken, geen kans om zich in de mond te vestigen. De samenstelling van het speekselmicrobioom is namelijk redelijk stabiel doordat de meeste micro-organismen in de mond vastzitten aan het oppervlak van het gebit en de zachte weefsels. Als je recent antibiotica hebt gebruikt, kun je beter niet zoenen met iemand die ontstoken tandvlees of cariës heeft.$$, 'inline'),
  ('326c33e0-9b11-4a47-9094-8f22c35a99b9', '8ae2dc5b-28ac-4a3e-bacf-280bf41621bd', $$afweer door lysozymen, antistoffen en zoutzuur$$,
   $$biologie-havo-2022-ii-zoenen-voor-de-wetenschap-context10.png$$,
   $$Een deel van de bacteriën die overgedragen worden, wordt in de mond al opgeruimd door lysozymen en antistoffen. De rest wordt gedood door het zoutzuur in de maag.$$, 'inline'),
  ('a3ee3adf-9559-42b3-ab0a-34d0c10a9889', '1f56913d-c82e-49c3-8040-53fa1687b520', $$inleiding: GM-gewassen met gifstoffen en resistentie$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context1.png$$,
   $$GM-gewassen zijn landbouwgewassen die genetisch gemodificeerd zijn. Veel GM-gewassen produceren gifstoffen die hen beter beschermen tegen vraat door insecten. Insecten ontwikkelen echter resistentie tegen deze gifstoffen.$$, 'inline'),
  ('d89db24c-2cd9-4e77-9732-6d74b49cdbb9', '1f56913d-c82e-49c3-8040-53fa1687b520', $$kader: het Cry-gen en darmperforatie bij insecten$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context2.png$$,
   $$Met behulp van DNA-technieken brachten onderzoekers het Cry-gen van de bodembacterie Bacillus thuringiensis in bij maisplanten en katoenplanten. Het Cry-gen codeert voor een eiwit dat giftig is voor insecten. Rupsen gaan enkele dagen na het eten van de planten dood, waardoor er veel minder bestrijdingsmiddelen gebruikt hoeven worden bij de teelt van deze gewassen. Het eiwit dat wordt gemaakt bij de expressie van het Cry-gen vormt eiwitkristallen. Deze kristallen lossen op bij een pH van 11 of hoger. Bij veel insecten is de pH van de darm hoger dan 11. De opgeloste Cry- eiwitten binden aan receptoren in het membraan van darmwandcellen, waarna er gaten in de darmwand ontstaan (perforatie). Als gevolg hiervan sterven de insecten.$$, 'inline'),
  ('81e182aa-88b5-4a19-a805-a03d8e04e956', '1f56913d-c82e-49c3-8040-53fa1687b520', $$Cry-eiwitten zijn voor mensen niet schadelijk$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context3.png$$,
   $$Voor mensen is het eten van planten met Cry-eiwitten niet schadelijk.$$, 'inline'),
  ('950afc31-a98b-4434-b5c5-277a71e2755e', '1f56913d-c82e-49c3-8040-53fa1687b520', $$kader: resistente katoendaguiltjes (afbeelding 1)$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context4.png$$,
   $$De genetische modificatie met het Cry-gen werd bij katoenplanten toegepast als bestrijdingsmethode tegen het katoendaguiltje (Helicoverpa armigera), dat zijn eitjes legt op katoenplanten. De rupsen van deze vlinder (afbeelding 1) eten van de katoenbladeren.
Een paar jaar na de introductie van de genetisch gemodificeerde katoenplanten werden er katoendaguiltjes gevonden die resistent waren tegen het Cry-eiwit.
afbeelding 1: foto van een rups op een blad$$, 'inline'),
  ('a6fa13fb-bc99-41b9-80a6-e310bdd2db9f', '1f56913d-c82e-49c3-8040-53fa1687b520', $$drie verklaringen voor de toename van resistentie$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context5.png$$,
   $$Het percentage resistente katoendaguiltjes op de GM-katoenplantages wordt elk jaar groter. Hiervoor worden de volgende verklaringen gegeven:
1 Dat is het gevolg van een verandering in een abiotische factor.
2 Niet-resistente rupsen gaan hun voedsel zoeken in plantages zonder genetisch gemodificeerde katoenplanten.
3 Resistente rupsen hebben een hogere fitness dan niet-resistente rupsen.$$, 'inline'),
  ('0f269502-a551-43fe-834e-7c0faffd215e', '1f56913d-c82e-49c3-8040-53fa1687b520', $$recessieve resistentie en stroken niet-GM-katoen$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context6.png$$,
   $$Resistentie tegen het Cry-eiwit is ontstaan door een mutatie in het gen dat codeert voor de receptor in het membraan van darmwandcellen. Hierdoor kan het giftige eiwit niet binden aan deze receptor. Het allel met deze mutatie is recessief. Alleen rupsen die homozygoot zijn voor de mutatie zijn resistent. Om te voorkomen dat deze resistentie zich verder verspreidt, worden in katoenplantages stroken ingezaaid met zaad van katoenplanten die niet genetisch gemodificeerd zijn.$$, 'inline'),
  ('880aaa3e-f4d2-4ca1-af40-13dfdc03003c', '1f56913d-c82e-49c3-8040-53fa1687b520', $$kader: puntmutatie in het HaTSPAN1-gen (serine i.p.v. leucine)$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context7.png$$,
   $$Een andere vorm van resistentie bij het katoendaguiltje wordt veroorzaakt door een puntmutatie in het HaTSPAN1-gen. Het mutante allel is dominant. Door de puntmutatie wordt op een positie in het HaTSPAN1- eiwit het aminozuur serine ingebouwd in plaats van leucine.$$, 'inline'),
  ('f0a3309b-4874-4fbd-99b1-111314b21eb2', '1f56913d-c82e-49c3-8040-53fa1687b520', $$de puntmutatie verandert één base in het mRNA$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context8.png$$,
   $$De puntmutatie leidt tot de verandering van één base in het mRNA.$$, 'inline'),
  ('a9b79048-4360-4c73-8c55-cbf5b8a47d3a', '1f56913d-c82e-49c3-8040-53fa1687b520', $$toename van het gemuteerde allel en een andere genetische modificatie$$,
   $$biologie-havo-2022-ii-insecten-resistent-tegen-gm-gewassen-context9.png$$,
   $$In tien jaar tijd is de allelfrequentie van het gemuteerde allel van het HaTSPAN1-gen met een factor 100 toegenomen. Hierdoor is het een serieuze bedreiging voor het succes van de GM-gewassen met het Cry- gen. Om resistentie in nieuwe plantages voor langere tijd te voorkomen willen de onderzoekers de genetische modificatie op een iets andere manier doen: ze willen het stuk DNA veranderen dat ze in de gewassen inbrengen.$$, 'inline'),
  ('9fc186d3-05bf-4dbe-b968-1d697920912f', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$inleiding: fantoompijn bestrijden met virtual reality$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context1.png$$,
   $$Corry van der Sluis is revalidatiearts en onderzoeker in het Universitair Medisch Centrum Groningen. Ze hoopt met behulp van virtual reality fantoompijn te kunnen bestrijden.$$, 'inline'),
  ('a7d85282-3328-4970-897c-0ed8ca3d603a', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$kader: ontstaan van een neuroma in vier stappen (afbeelding 1)$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context2.png$$,
   $$Fantoompijn is pijn die gevoeld wordt in een geamputeerd deel van het lichaam. Een theorie is dat het pijngevoel wordt veroorzaakt door een zogenoemd neuroma, dat gevormd wordt op de plaats waar een perifere zenuw doorgesneden is als gevolg van een amputatie. Het ontstaan van een neuroma is in afbeelding 1 in vier stappen weergegeven:
1 Een gezonde sensorische zenuwcel heeft een dendriet met een myelineschede.
2 Na de amputatie ruimen witte bloedcellen celresten op rondom de beschadigde zenuwcel.
3 De zenuwcel vormt nieuwe uitlopers.
4 De nieuwe uitlopers van meerdere zenuwcellen vormen een kluwen: een neuroma.
afbeelding 1: tekeningen van de vier stappen; een pijl geeft de richting van de impulsgeleiding aan.$$, 'inline'),
  ('679761ee-6d43-4bfe-8f91-c759b5855872', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$spontane actiepotentialen in het neuroma$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context3.png$$,
   $$In het neuroma kunnen spontaan actiepotentialen (impulsen) ontstaan die leiden tot het pijngevoel.$$, 'inline'),
  ('9e539bfe-6838-4a32-9081-b7370c4136c0', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$sneller actiepotentialen in een neuroma$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context4.png$$,
   $$Bij de zenuwcellen in een neuroma kunnen sneller actiepotentialen ontstaan dan in normale zenuwcellen.$$, 'inline'),
  ('6ffe58bc-b85f-453c-8898-64fdf9585cc8', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$kader: reorganisatie van centra in de hersenschors$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context5.png$$,
   $$Een tweede theorie is dat fantoompijn ontstaat doordat bepaalde centra van de hersenschors zijn gereorganiseerd. Sensorische en motorische gebieden die als gevolg van de amputatie ‘werkeloos’ zijn, worden in gebruik genomen door naastgelegen hersengebieden.$$, 'inline'),
  ('fe8d82c5-f0d1-4a83-90ce-9b7aa256bf04', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$een werkeloos gebied wordt gebruikt door het gebied voor het gezicht$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context6.png$$,
   $$In afbeelding 2 is met een zwarte cirkel een gebied van de hersenschors aangegeven dat werkeloos is als gevolg van de amputatie van een hand. Dit gebied wordt nu gebruikt door een nabijgelegen hersengebied dat sensorische informatie van het gezicht verwerkt.$$, 'inline'),
  ('d666bc1d-3d00-461c-84e3-cdf91f03c338', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$afbeelding 2: grote hersenen met de centrale groeve en de letters P tot en met T$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context7.png$$,
   $$afbeelding 2: zijaanzicht van de hersenen met de centrale groeve. Links van de centrale groeve wijzen P, Q en R naar gebieden van de hersenschors, rechts ervan wijzen S en T naar gebieden; een donkere cirkel geeft het werkeloze gebied aan.$$, 'inline'),
  ('c39c5da6-786f-4406-ac88-2b0c78d01fa7', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$kader: behandeling met elektrodes en een virtuele arm (afbeelding 3 en 4)$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context8.png$$,
   $$Corry van der Sluis behandelt patiënten met fantoompijn met behulp van virtual reality.
Een man die lijdt aan fantoompijn krijgt elektrodes op de stomp van zijn geamputeerde arm geplakt (afbeelding 3). Met de elektrodes worden elektrische signalen opgevangen die ontstaan in de spieren in de stomp wanneer hij zijn ontbrekende onderarm probeert te bewegen. Op een beeldscherm ziet hij zichzelf bewegingen maken met zijn virtuele arm (afbeelding 4).
Door te oefenen worden de bewegingen preciezer en kan hij steeds moeilijkere opdrachten uitvoeren. Na tien sessies heeft de man voor het eerst in 50 jaar momenten zonder fantoompijn.
afbeelding 3: foto van een armstomp met elektrodes
afbeelding 4: foto van de man voor een beeldscherm met een virtuele arm$$, 'inline'),
  ('99b4728e-70e8-44da-bd7d-1d7309b69297', '43fbe09f-09bc-4de9-a2ac-d23516c3efa4', $$het gebied waar het beeld wordt gevormd en het gebied dat spieren aanstuurt$$,
   $$biologie-havo-2022-ii-fantoompijn-bestrijden-met-virtual-reality-context9.png$$,
   $$Op het beeldscherm ziet de man de bewegingen die hij probeert te maken. Het lukt hem om de bewegingen steeds nauwkeuriger te maken doordat het gebied in de hersenen waar het beeld wordt gevormd, in contact staat met het gebied dat de spieren aanstuurt.$$, 'inline'),
  ('a08215ff-1afc-429c-a66a-a44a8db049de', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$inleiding: populatiedichtheid van de grootste bloedzuiger bepalen$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context1.png$$,
   $$De grootste bloedzuiger van Nederland stelt hoge eisen aan zijn leefgebied. In Nederland zijn nog maar een paar van deze gebieden. De ecologen Ron Felix en Bram Koese onderzoeken verschillende methodes om de populatiedichtheid van deze soort te bepalen.$$, 'inline'),
  ('b6841efb-0993-4978-9009-22d19b07fa6d', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$kader: habitat van Hirudo medicinalis (afbeelding 1)$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context2.png$$,
   $$De bloedzuiger Hirudo medicinalis (afbeelding 1) komt voor in vennetjes, beekjes en moerassen. Zijn habitat moet aan een aantal kenmerken voldoen. De eieren moeten in een zelfgemaakt kuiltje op een zandige oever naast ondiep water gelegd kunnen worden, waar ze door de warmte van de zon tot ontwikkeling kunnen komen.
Ook moet er voldoende voedsel aanwezig zijn. De larven eten de eerste dagen waterslakjes. Waterslakken komen alleen voor in water met een pH hoger dan 5,5. Na een aantal dagen stapt de bloedzuiger over op bloed van amfibieën en van zoogdieren, zoals reeën en grote grazers, die het water inlopen om te drinken.
afbeelding 1: foto van een bloedzuiger in ondiep water$$, 'inline'),
  ('38cf943e-3701-4a72-a9bc-fe03225c2ab1', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$vier milieufactoren die het aantal bloedzuigers beïnvloeden$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context3.png$$,
   $$Verschillende milieufactoren zijn van invloed op het aantal bloedzuigers. Enkele van deze factoren zijn:
1 diepte van het water
2 pH van het water
3 waterslakjes
4 zandige oever$$, 'inline'),
  ('f49b651d-c2ac-44b7-acfb-daa049cdca23', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$vier relaties tussen organismen$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context4.png$$,
   $$Tussen organismen kunnen verschillende relaties voorkomen. Vier relaties zijn: commensalisme; mutualisme; parasitisme; predatie.$$, 'inline'),
  ('bd205a28-9a47-4b7f-8703-3cbdd6c9d706', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$kader: bloedzuiger zuigt bloed van een zoogdier$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context5.png$$,
   $$Als een zoogdier het water inloopt, veroorzaakt dit trillingen die door de bloedzuigers waargenomen worden. Ze zwemmen vervolgens razendsnel op hun doel af, zuigen zich vast met hun zuignap en maken met hun scherpe tandjes een wondje. In het speeksel van de bloedzuiger zit een stof die de plaats van de bijtwond verdooft, en een stof die de bloedstolling remt (hirudine). De bloedzuiger kan daardoor in dertig minuten zoveel bloed opzuigen, dat zijn gewicht vertienvoudigt. Daarna laat hij los.$$, 'inline'),
  ('b8b97d2e-f049-4bef-8d22-c3d963061fec', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$de verdovende stof is gedurende de evolutie ontstaan$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context6.png$$,
   $$Het produceren van de verdovende stof is gedurende de evolutie ontstaan.$$, 'inline'),
  ('534abdb6-2739-461b-b3bc-fe927a192f21', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$hirudine blokkeert trombine bij de bloedstolling$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context7.png$$,
   $$Hirudine blokkeert het enzym trombine, dat nodig is voor de bloedstolling. In normale situaties veroorzaakt trombine de omzetting van een oplosbaar plasma-eiwit naar onoplosbare eiwitdraden, waardoor een netwerk ontstaat waarin bloedcellen blijven hangen: een bloedstolsel. Door de werking van hirudine ontstaat er geen stolsel, waardoor de bijtwond blijft bloeden. Afbeelding 2 is een schematische weergave van dit proces. Hierin zijn vier eiwitten met een nummer aangegeven.$$, 'inline'),
  ('82b94ff0-d6c7-449c-84f1-992b06aef0cc', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$afbeelding 2: schema van de bloedstolling met vier genummerde eiwitten$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context8.png$$,
   $$afbeelding 2: schema van de bloedstolling. Eiwit 1: losse kleine moleculen; eiwit 2: een L-vormig molecuul; eiwit 3: een groot zwart molecuul met een bindingsplaats voor het substraat (*); eiwit 4: een netwerk van aan elkaar gekoppelde moleculen. Een pijl loopt van de losse moleculen naar het netwerk; een afbuigende pijl geeft afsplitsing van kleine deeltjes aan.
Legenda: * bindingsplaats substraat$$, 'inline'),
  ('94f636d7-237c-41ff-b09d-a90a310b7351', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$de namen van de vier eiwitten$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context9.png$$,
   $$De vier genummerde eiwitten in afbeelding 2 zijn:
− fibrine
− fibrinogeen
− hirudine
− trombine$$, 'inline'),
  ('4b355e0b-6d64-4d82-9557-eeee6c3de5db', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$bloedzuigers zoeken met blote benen (afbeelding 3)$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context10.png$$,
   $$Bloedzuigers zoeken met blote benen is niet moeilijk: je loopt een vennetje in en als ze aanwezig zijn, zitten ze binnen een paar minuten op je benen (afbeelding 3).
Een nadeel van deze manier van inventariseren is dat je er een verdoofd gevoel in je been van krijgt en de wondjes langdurig blijven bloeden.
afbeelding 3: foto van een bloedzuiger op een voet$$, 'inline'),
  ('5a564f66-2658-4a77-a252-4f0598965c69', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$vergelijkend onderzoek met blote benen en lieslaarzen$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context11.png$$,
   $$Felix en Koese voeren daarom een vergelijkend onderzoek uit. De onderzoeksvraag is: trekken benen in lieslaarzen ook bloedzuigers aan? In afbeelding 4 zie je de twee ecologen rondlopen in een vennetje. Alle aangetrokken bloedzuigers worden gevangen en tijdelijk in een emmertje bewaard. De bloedzuigers blijken zowel op blote benen als op benen in lieslaarzen af te komen.$$, 'inline'),
  ('474df7eb-cc91-4f48-b221-eb4340e20270', '443c0c16-6a23-4e4f-9d21-120084a6ff16', $$afbeelding 4: de ecologen in een vennetje$$,
   $$biologie-havo-2022-ii-op-zoek-naar-de-grootste-bloedzuiger-van-nederland-context12.png$$,
   $$afbeelding 4: foto van de twee ecologen die rondlopen in een vennetje, de een in lieslaarzen en de ander met blote benen.$$, 'inline');

