   $$biologie-havo-2022-ii-borstvoeding-vraag17.png$$, $$1p 17 Verklaar waardoor een toename in darmperistaltiek leidt tot een verminderde waterresorptie.$$, array['a2675600-7d19-4fbd-9acd-2ea5b7e2bf98']::uuid[]),
